-- EVT lua patch for bb_stadium_top_menu (common/script/lua/menu/bb_stadium_top_menu_1.03.98.00.lua.bin). Graft bb_active_team. Generated by research/scripts/menu_assemble.py (build --out patches) from research/grafts/; do not edit by hand.
-- ===== EVT bb_active_team common BEGIN =====
-- BattleBayDeluxe bb_active_team, shared part (enjoy_team_select_menu_campaign / _offline, bb_stadium_top_menu,
-- soccer_top_menu; docs/game/modes/estadio-bb.md §16.4). The «Active team» tile (evt_bbd_active_team) is the player's
-- ACTIVE TEAM: the VS team set the game plays outside the Battle Bay (CMND_GET_VS_USE_TEAM_SET), read here every time
-- it is needed, never a fixed team. 1.5.64 (owner 2026-10-14: the tile showed Mark Evans / Raimon, its line-up and
-- tactics, and the pre-match talk two Mark Evans):
--   * BBD_ACTIVE_TEAM_Read: the active team set's line-up (position -> chara_param), captain, formation, emblem,
--     tactics, name and kit, from the game's own team-set commands (as the team dock reads them);
--   * BBD_ACTIVE_TEAM_Sync: the line-up, captain, team set, emblem, kit and name sent to the mod's scripts
--     (CMND_BBD_ACTIVE_TEAM_MIRROR, scripts\active_team.lua), which write them over the tile's member rows, its Battle
--     Bay row's leader and its team record (crest, kit) in memory, and the crest, kit and match name onto the Draft
--     team (1.5.77: the Draft plays as the active team's club): every reader of the tile (the grid's crest and model,
--     the panel cards, the big portrait = the row's leader, the campaign scene and its pre-match talk speaker) then
--     sees the active team. The match itself plays that team set (content\game\active_team.toml: its players, moves,
--     kit and crest, at the Battle Bay's level sync).
-- Globals only (BBD_ACTIVE_TEAM*); nothing runs at chunk load.
BBD_ACTIVE_TEAM = BBD_ACTIVE_TEAM or {}
do
  local B = BBD_ACTIVE_TEAM
  B.TEAM = 1606221734
  B.MIRROR = 3400562632
  B.VS_SET = 3713813716
  B.MEMBER = 1720957768 --[[team set member (set, team type, i, 0 handle / 1 position)]]
  B.STATUS = 1131797651 --[[character status (handle, 4 chara_param)]]
  B.SET_INFO = 1033065575 --[[CMND_GET_TEAM_SET_INFO (set, team type, field, …)]]
  B.TEAM_TYPE = 0          -- the 11-a-side team of the set
  B.MEMBERS = 29           -- member indexes of a team set (the team dock's 29 slots)
  B.SQUAD_LAST = 18        -- positions 0-10 the starters, 11-18 the bench (as the Battle Bay squads)
  B.TACTICS = 3            -- tactics slots of a team set
  B.FIELD_FORMATION, B.FIELD_EMBLEM, B.FIELD_NAME, B.FIELD_UNIFORM, B.FIELD_CAPTAIN, B.FIELD_TACTIC = 4, 5, 6, 7, 8, 9
  B.sent = B.sent or nil   -- the line-up text last mirrored by this menu

  -- the logger (VRFW_Log), made at the first line: the framework's menu files load after the graft blocks
  function BBD_ACTIVE_TEAM_Logger()
    B.logger = B.logger or VRFW_Log.New("BattleBayDeluxe.active_team")
    return B.logger
  end

  function BBD_ACTIVE_TEAM_Log(...)
    BBD_ACTIVE_TEAM_Logger()(...)
  end

  -- the active team set: { set, lineup = { [position] = chara_param }, captain, formation, emblem, uniform,
  -- tactics = { [i] }, name, text = "position:param,…" }; nil + why when the game answers no team set
  function BBD_ACTIVE_TEAM_Read()
    local okset, set = pcall(funcLuaCommand, B.VS_SET)
    if not okset or type(set) ~= "number" or set < 0 then
      return nil, "no active team set (CMND_GET_VS_USE_TEAM_SET " .. tostring(set) .. ")"
    end
    local d = { set = set, lineup = {}, captain = 0, tactics = {}, name = "" }
    local parts = {}
    for k = 0, B.MEMBERS - 1 do
      local okh, has, hdl = pcall(funcLuaCommand, B.MEMBER, set, B.TEAM_TYPE, k, 0)
      if okh and has and type(hdl) == "number" and hdl ~= 0 then
        local okp, hasp, pos = pcall(funcLuaCommand, B.MEMBER, set, B.TEAM_TYPE, k, 1)
        if okp and hasp and type(pos) == "number" and pos >= 0 and pos <= B.SQUAD_LAST and d.lineup[pos] == nil then
          local okc, card = pcall(funcLuaCommand, B.STATUS, hdl, 4)
          card = okc and VRFW_Id.u32(card) or 0
          if card ~= 0 then
            d.lineup[pos] = card
            parts[#parts + 1] = string.format("%d:%.0f", pos, card)   -- %.0f: the game's %d stops at 2^31
            local okk, hask, captain = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_CAPTAIN, hdl)
            if okk and hask and captain == true then
              d.captain = card
            end
          end
        end
      end
    end
    if #parts == 0 then
      return nil, "the active team set " .. set .. " has no players"
    end
    local okf, hasf, formation = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_FORMATION)
    if okf and hasf and type(formation) == "number" and formation ~= 0 then
      d.formation = formation
    end
    local oke, hase, emblem = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_EMBLEM, 0)
    if oke and hase and type(emblem) == "number" and emblem ~= 0 then
      d.emblem = emblem
    end
    local oku, hasu, uniform = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_UNIFORM)
    if oku and hasu and type(uniform) == "number" and uniform ~= 0 then
      d.uniform = uniform
    end
    local okn, hasn, name = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_NAME)
    if okn and hasn and type(name) == "string" then
      d.name = name
    end
    for i = 0, B.TACTICS - 1 do
      local okt, hast, tactic = pcall(funcLuaCommand, B.SET_INFO, set, B.TEAM_TYPE, B.FIELD_TACTIC, i)
      d.tactics[i] = (okt and hast and type(tactic) == "number") and tactic or 0
    end
    d.text = table.concat(parts, ",")
    return d
  end

  -- the active team read and mirrored onto the tile (once per change in this menu); the team set's data, or nil
  function BBD_ACTIVE_TEAM_Sync(why)
    local d, err = BBD_ACTIVE_TEAM_Read()
    if not d then
      if B.read_error ~= err then
        B.read_error = err
        BBD_ACTIVE_TEAM_Log("not read (" .. tostring(why) .. "): " .. tostring(err))
      end
      return nil
    end
    B.read_error = nil
    -- %.0f: the game's %d stops at 2^31
    local key = string.format("%s|%.0f|%d|%.0f|%.0f|%s", d.text, d.captain, d.set, d.emblem or 0, d.uniform or 0, d.name)
    if B.sent ~= key then
      local ok, done, info = pcall(funcLuaCommand, B.MIRROR, d.captain, d.text, d.set, d.emblem or 0, d.uniform or 0,
        d.name)
      if ok and done == true then
        B.sent = key
      end
      BBD_ACTIVE_TEAM_Log("mirror (" .. tostring(why) .. "): team set " .. d.set .. ", " .. tostring(info or done) ..
        (ok and "" or " (the scripts were busy: again next time)"))
    end
    B.data = d
    return d
  end
end
-- ===== EVT bb_active_team common END =====

